order = _item["json"]
errors = []

required_fields = {
    "external_order_id": "External Order ID",
    "customer_name": "Customer Name",
    "customer_email": "Customer Email",
    "pickup_address": "Pickup Address",
    "delivery_address": "Delivery Address",
    "package_size": "Package Size",
    "priority": "Priority",
    "vehicle_required": "Vehicle Required",
    "delivery_time_window": "Delivery Time Window",
    "fragile_package": "Fragile Package",
    "special_delivery_instructions": "Special Delivery Instructions"
}

for field_name, field_label in required_fields.items():
    value = str(order.get(field_name, "")).strip()

    if not value:
        errors.append(f"{field_label} is missing")

customer_email = str(
    order.get("customer_email", "")
).strip()

if customer_email:
    email_parts = customer_email.split("@")

    if (
        len(email_parts) != 2
        or not email_parts[0]
        or "." not in email_parts[1]
    ):
        errors.append("Customer Email is invalid")

pickup_address = str(
    order.get("pickup_address", "")
).strip()

if pickup_address:
    if not any(character.isdigit() for character in pickup_address):
        errors.append(
            "Pickup Address needs attention. "
            "Please provide a house or building number."
        )

delivery_address = str(
    order.get("delivery_address", "")
).strip()

if delivery_address:
    if not any(character.isdigit() for character in delivery_address):
        errors.append(
            "Delivery Address needs attention. "
            "Please provide a house or building number."
        )

validation_passed = len(errors) == 0

output = {
    **order,
    "validation_passed": validation_passed,
    "validation_errors": errors,
    "order_status": (
        "Validated"
        if validation_passed
        else "Needs Attention"
    )
}

return {"json": output}

order = _item["json"]


providers = order.get("provider_quotes", [])

required_vehicle = str(
    order.get("vehicle_required", "")
).strip().lower()

minimum_reliability = float(
    order.get("minimum_reliability", 0)
)

maximum_eta_minutes = float(
    order.get("maximum_eta_minutes", 120)
)

eligible_providers = []
rejected_providers = []

for provider in providers:
    supported_vehicles = [
        str(vehicle).strip().lower()
        for vehicle in provider.get("vehicle_sizes", [])
    ]

    has_required_vehicle = (
        required_vehicle in supported_vehicles
    )

    is_available = bool(
        provider.get("available", False)
    )

    is_reliable_enough = (
        float(provider.get("reliability_score", 0))
        >= minimum_reliability
    )

    is_fast_enough = (
        float(provider.get("eta_minutes", 999))
        <= maximum_eta_minutes
    )

    rejection_reasons = []

    if not is_available:
        rejection_reasons.append("Provider is not available")

    if not has_required_vehicle:
        rejection_reasons.append(
            "Required vehicle is not supported"
        )

    if not is_reliable_enough:
        rejection_reasons.append(
            "Below minimum reliability"
        )

    if not is_fast_enough:
        rejection_reasons.append(
            "Cannot meet maximum ETA"
        )

    if len(rejection_reasons) == 0:
        eligible_providers.append(provider)
    else:
        rejected_providers.append({
            "provider_id": provider.get("provider_id"),
            "provider_name": provider.get("provider_name"),
            "rejection_reasons": rejection_reasons
        })

output = {
    **order,
    "eligible_providers": eligible_providers,
    "rejected_providers": rejected_providers,
    "eligible_provider_count": len(eligible_providers),
    "rejected_provider_count": len(rejected_providers)
}

return {"json": output}

order = _item["json"]

providers = list(order.get("eligible_providers", []))
strategy = str(order.get("dispatch_strategy", "")).strip()

if strategy == "Highest Reliability":
    providers.sort(
        key=lambda provider: (
            -float(provider.get("reliability_score", 0)),
            float(provider.get("delivery_fee", 999))
        )
    )

elif strategy == "Fastest Eligible":
    providers.sort(
        key=lambda provider: (
            float(provider.get("eta_minutes", 999)),
            -float(provider.get("reliability_score", 0))
        )
    )

elif strategy == "Balanced Speed Reliability":
    providers.sort(
        key=lambda provider: (
            float(provider.get("eta_minutes", 999)),
            -float(provider.get("reliability_score", 0)),
            float(provider.get("delivery_fee", 999))
        )
    )

elif strategy == "Vehicle Capacity First":
    providers.sort(
        key=lambda provider: (
            -float(provider.get("reliability_score", 0)),
            float(provider.get("eta_minutes", 999))
        )
    )

else:
    providers.sort(
        key=lambda provider: (
            float(provider.get("delivery_fee", 999)),
            -float(provider.get("reliability_score", 0))
        )
    )

selected_provider = providers[0]
fallback_providers = providers[1:]

fallback_provider = (
  fallback_providers[0]
  if fallback_providers
  else " No Eligible Provider"
)

output = {
    **order,
    "selected_provider": selected_provider,
    "fallback_provider": fallback_provider,
    "fallback_providers": fallback_providers,
    "fallback_provider": None,
    "selection_reason": (
        f"Selected {selected_provider.get('provider_name')} "
        f"using the {strategy} strategy."
    )
}

return {"json": output}

