order = _item["json"]

fallback_providers = list(
    order.get("fallback_providers", [])
)

failed_provider = (
    order.get("failed_provider")
    or order.get("selected_provider")
    or {}
)

if isinstance(failed_provider, dict):
    failed_provider_name = str(
        failed_provider.get("provider_name", "")
    ).strip()
else:
    failed_provider_name = str(
        failed_provider
    ).strip()

selected_fallback = None
remaining_fallbacks = []

for provider in fallback_providers:

    if (
        provider.get("provider_name")
        == failed_provider_name
    ):
        continue

    if not provider.get("available", False):
        continue

    if selected_fallback is None:
        selected_fallback = provider
    else:
        remaining_fallbacks.append(provider)

fallback_provider_found = (
    selected_fallback is not None
)

primary_failure_reason = str(
    order.get(
        "primary_failure_reason",
        "Primary provider failed."
    )
).strip().rstrip(".")

if fallback_provider_found:
    reassignment_failure_reason = ""
else:
    reassignment_failure_reason = (
        f"{primary_failure_reason}. "
        "No remaining eligible provider was available."
    )

output = {
    **order,
    "failed_provider": failed_provider,
    "fallback_provider_found": fallback_provider_found,
    "fallback_provider": selected_fallback,
    "selected_provider": (
        selected_fallback
        if fallback_provider_found
        else order.get("selected_provider")
    ),
    "remaining_fallback_providers": remaining_fallbacks,
    "reassignment_required": True,
    "reassignment_failure_reason": (
        reassignment_failure_reason
    )
}

return {"json": output}

